package pl.kurs.review;

import java.math.BigDecimal;

/**
 * A book. Turn it into a JPA entity (see ZADANIE.md): the id is generated by the database,
 * the ISBN is unique. Keep the constructor and the getters: the tests use them.
 */
public class Book {

    private Long id;
    private String title;
    private String author;
    private String isbn;
    private BigDecimal price;
    private int publishedYear;

    public Book(String title, String author, String isbn, BigDecimal price, int publishedYear) {
        this.title = title;
        this.author = author;
        this.isbn = isbn;
        this.price = price;
        this.publishedYear = publishedYear;
    }

    public Long getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public String getAuthor() {
        return author;
    }

    public String getIsbn() {
        return isbn;
    }

    public BigDecimal getPrice() {
        return price;
    }

    public int getPublishedYear() {
        return publishedYear;
    }
}
